import type { NextRequest } from "next/server";

import { HttpError, handle, json, readJson } from "@/lib/api/http";
import { requireActiveSubscription } from "@/lib/auth/guards";
import { toHttpError } from "@/lib/host/errors";
import { parseGameInput } from "@/lib/host/validation";

/**
 * Create a game (protected). Order: authenticated + ACTIVE subscription ->
 * validate against the caller's plan -> one atomic RPC running as the caller.
 * The room code is generated by the database (CSPRNG, unique); the game id is a
 * random UUID, so neither is derived from guessable counters.
 */
export async function POST(request: NextRequest) {
  return handle(async () => {
    const { supabase, entitlement } = await requireActiveSubscription();

    const parsed = parseGameInput(await readJson(request), entitlement.max_rounds_per_game);
    if (!parsed.ok) throw new HttpError(parsed.error === "too_many_items" ? 422 : 400, parsed.error);

    const { data, error } = await supabase.rpc("create_game_with_rounds", {
      p_title: parsed.value.title,
      p_items: parsed.value.items,
    });
    if (error || !data?.[0]) throw toHttpError(error?.message ?? "");
    return json({ id: data[0].game_id, code: data[0].code }, 201);
  });
}
